const SERIES = {
  workouts100: '100 Workouts/100 Workouts',
  workouts200: '200 Workouts/200 Workouts',
  female100: '430 Workouts/430 Workouts/100 female Gym',
  female200: '430 Workouts/430 Workouts/200 female gym',
  male130: '430 Workouts/430 Workouts/130 male gym',
}

function exercise(id, series, purchasedName, name, muscleGroup, inputKind, equipment, primaryMuscleDetail, purposes = [], aliases = [], instructions) {
  return {
    ref: `vital-gym-pro-${id}`,
    purchasedId: id,
    purchasedName,
    sourceFile: `${SERIES[series]}/${id}.mp4`,
    name,
    englishName: purchasedName,
    muscleGroup,
    inputKind,
    equipment,
    primaryMuscleDetail,
    purposes,
    aliases,
    legacyFitRefs: [],
    ...(instructions ? { instructions } : {}),
  }
}

